@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments - Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="filterStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (showCreate)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-2">
                    <input class="form-control" placeholder="Customer email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-1 d-flex gap-1">
                    <button class="btn btn-success btn-sm" @onclick="CreateShipment" disabled="@isCreating">Save</button>
                    <button class="btn btn-secondary btn-sm" @onclick="() => showCreate = false">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Description</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Description</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                    <td>@s.CustomerEmail</td>
                    <td>
                        @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                        {
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    value="@s.Status"
                                    @onchange="(e) => OnStatusChanged(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match the current filter.</p>
    }
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;
    private bool showCreate;
    private bool isCreating;
    private Shipment newShipment = new();

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrWhiteSpace(filterText) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrWhiteSpace(filterStatus) ||
             s.Status.ToString() == filterStatus));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment { EstimatedDelivery = DateTime.Today.AddDays(5) };
        showCreate = true;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            shipments = await ShipmentService.GetAllShipmentsAsync();
            showCreate = false;
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task OnStatusChanged(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/"
@page "/track"
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p class="lead">Enter your tracking number to check the status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
